// Scores every pair of Clio contacts for duplicate likelihood. Solo/small firm contact
// volumes (a few hundred) make an O(n^2) in-memory comparison practical here -- no
// external fuzzy-match service needed.

function normalizeText(s) {
  return String(s || '').trim().toLowerCase().replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, ' ');
}
function normalizePhone(s) {
  return String(s || '').replace(/\D/g, '');
}
function normalizeEmail(s) {
  return String(s || '').trim().toLowerCase();
}
function levenshtein(a, b) {
  if (a === b) return 0;
  if (!a.length) return b.length;
  if (!b.length) return a.length;
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      cur[j] = Math.min(cur[j - 1] + 1, prev[j] + 1, prev[j - 1] + cost);
    }
    prev = cur;
  }
  return prev[b.length];
}
function nameSimilarity(a, b) {
  const na = normalizeText(a), nb = normalizeText(b);
  if (!na || !nb) return 0;
  if (na === nb) return 100;
  const maxLen = Math.max(na.length, nb.length);
  return Math.round((1 - levenshtein(na, nb) / maxLen) * 100);
}

// httpRequest returns Clio's raw response envelope as a single item -- read .data
// directly rather than relying on any node option to auto-split it into items.
const responseBody = $input.first().json;
const rawContacts  = responseBody.data || [];

const contacts = rawContacts
  .filter(c => c && c.id)
  .map(c => ({
    id:    c.id,
    name:  c.name || [c.first_name, c.last_name].filter(Boolean).join(' '),
    email: normalizeEmail(c.primary_email_address),
    phone: normalizePhone(c.primary_phone_number),
    type:  c.type || 'Person',
  }));

const pairs = [];
for (let i = 0; i < contacts.length; i++) {
  for (let j = i + 1; j < contacts.length; j++) {
    const a = contacts[i], b = contacts[j];
    if (a.type !== b.type) continue; // never compare a Person against a Company

    const emailMatch = !!(a.email && b.email && a.email === b.email);
    const phoneMatch = !!(a.phone && b.phone && a.phone.length >= 7 && a.phone === b.phone);
    const nameScore  = nameSimilarity(a.name, b.name);

    // Exact email or phone match is a strong signal on its own -- weighted equally, since
    // either one plus a reasonably-similar name should clear the default threshold on its
    // own. Name similarity alone tops out at 30, so two different 'John Smith's with no
    // matching email or phone never trip this by name alone.
    let confidence = 0;
    if (emailMatch) confidence += 50;
    if (phoneMatch) confidence += 50;
    confidence += Math.round(nameScore * 0.30);
    confidence = Math.min(confidence, 100);

    if (confidence < 40) continue; // below the noise floor, don't carry forward

    pairs.push({
      pair_id: [a.id, b.id].sort((x, y) => x - y).join('-'),
      contact_a_id: a.id, contact_a_name: a.name, contact_a_email: a.email, contact_a_phone: a.phone,
      contact_b_id: b.id, contact_b_name: b.name, contact_b_email: b.email, contact_b_phone: b.phone,
      email_match: emailMatch, phone_match: phoneMatch, name_similarity: nameScore,
      confidence,
    });
  }
}

pairs.sort((a, b) => b.confidence - a.confidence);

return [{ json: {
  pairs,
  pair_count: pairs.length,
  has_pairs: pairs.length > 0,
  scanned_at: new Date().toISOString(),
} }];

// Filters candidate pairs down to ones above the confidence threshold that haven't
// already been flagged or dismissed -- uses n8n's built-in workflow static data (global
// scope, shared with the Dismiss webhook path below) so a pair isn't re-reported every
// single day once a human has seen it. No external database.
const THRESHOLD = Number($vars.DUPLICATE_CONFIDENCE_THRESHOLD) || 70;

const input = $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.seenPairs) staticData.seenPairs = {}; // pair_id -> { status: 'flagged'|'dismissed', at: ISOString }

const NINETY_DAYS_MS = 90 * 24 * 60 * 60 * 1000;
const now = Date.now();
for (const [id, rec] of Object.entries(staticData.seenPairs)) {
  if (now - new Date(rec.at).getTime() > NINETY_DAYS_MS) delete staticData.seenPairs[id];
}

const newPairs = [];
for (const pair of (input.pairs || [])) {
  if (pair.confidence < THRESHOLD) continue;
  if (staticData.seenPairs[pair.pair_id]) continue; // already flagged or dismissed -- don't ask twice
  newPairs.push(pair);
  staticData.seenPairs[pair.pair_id] = { status: 'flagged', at: new Date().toISOString() };
}

return [{ json: {
  new_pairs: newPairs,
  new_pair_count: newPairs.length,
  has_new_pairs: newPairs.length > 0,
  threshold: THRESHOLD,
  scanned_at: input.scanned_at,
} }];

// Builds the digest email listing every newly-flagged pair, with a direct link to view
// both contacts in Clio and a one-click Dismiss link per pair that suppresses it from
// future scans. Clio has no merge feature -- not in the app, not via API -- so merging
// stays a manual step the paralegal does in Clio itself; this email points them at it.
const FIRM_NAME        = $vars.FIRM_NAME;
const PARALEGAL_EMAIL  = $vars.FIRM_PARALEGAL_EMAIL || $vars.FIRM_EMAIL;
const FROM_EMAIL       = $vars.FIRM_FROM_EMAIL;
const CLIO_BASE_URL    = $vars.CLIO_BASE_URL;
const DISMISS_BASE_URL = $vars.DUPLICATE_DISMISS_WEBHOOK_URL;

if (!FIRM_NAME)        throw new Error('FIRM_NAME n8n Variable is not set. Go to Settings → Variables and add it.');
if (!PARALEGAL_EMAIL)  throw new Error('Neither FIRM_PARALEGAL_EMAIL nor FIRM_EMAIL n8n Variable is set. Go to Settings → Variables and add at least one.');
if (!FROM_EMAIL)       throw new Error('FIRM_FROM_EMAIL n8n Variable is not set. Go to Settings → Variables and add it.');
if (!CLIO_BASE_URL)    throw new Error('CLIO_BASE_URL n8n Variable is not set (e.g. https://app.clio.com or https://eu.app.clio.com).');
if (!DISMISS_BASE_URL) throw new Error('DUPLICATE_DISMISS_WEBHOOK_URL n8n Variable is not set. Activate this workflow, copy the "When Dismiss Link Clicked" node\'s Production URL, and set it here.');

const item = $input.first().json;
const DIV = '─'.repeat(60);

const rows = item.new_pairs.map((p, idx) => {
  const linkA = `${CLIO_BASE_URL}/nc/#/contacts/${p.contact_a_id}`;
  const linkB = `${CLIO_BASE_URL}/nc/#/contacts/${p.contact_b_id}`;
  const dismissLink = `${DISMISS_BASE_URL}?pair_id=${encodeURIComponent(p.pair_id)}`;
  const signals = [
    p.email_match ? 'same email' : null,
    p.phone_match ? 'same phone' : null,
    `name ${p.name_similarity}% similar`,
  ].filter(Boolean).join(', ');

  return [
    `${idx + 1}. ${p.confidence}% confidence — ${signals}`,
    `   A: ${p.contact_a_name}  ${p.contact_a_email || '(no email)'}  ${p.contact_a_phone || '(no phone)'}`,
    `   ${linkA}`,
    `   B: ${p.contact_b_name}  ${p.contact_b_email || '(no email)'}  ${p.contact_b_phone || '(no phone)'}`,
    `   ${linkB}`,
    `   Not a duplicate? Dismiss it: ${dismissLink}`,
  ].join('\n');
});

const email_subject = `${item.new_pair_count} possible duplicate contact${item.new_pair_count === 1 ? '' : 's'} in Clio — ${FIRM_NAME}`;

const email_body = [
  `${item.new_pair_count} likely-duplicate contact pair${item.new_pair_count === 1 ? '' : 's'} found in today's scan.`,
  '',
  'Clio has no merge feature — not in the app, not via API. To combine two contacts: open both, copy anything missing from the older record into the one you want to keep, then delete the other. See "Is There a Way to Merge Contacts?" in Clio\'s Help Center for their official steps.',
  '',
  DIV,
  rows.join('\n' + DIV + '\n'),
  DIV,
  '',
  `Threshold: pairs are only reported at ${item.threshold}%+ confidence. Each pair is reported once — dismissing it (or merging it) means it won't show up again in a future scan.`,
  `Scanned: ${item.scanned_at}`,
].join('\n');

return [{ json: {
  ...item,
  firm_name: FIRM_NAME,
  paralegal_email: PARALEGAL_EMAIL,
  from_email: FROM_EMAIL,
  email_subject,
  email_body,
} }];

// Marks a pair as dismissed so it never gets re-flagged, and builds the confirmation
// page the paralegal sees after clicking the Dismiss link from the alert email.
// Uses the same global-scope static data as 'Filter To New High-Confidence Pairs' --
// node-scoped static data would give this node its own isolated store and the dismissal
// would silently fail to suppress future re-flagging.
const raw = $input.first().json;
const query = raw.query || {};
const pairId = String(query.pair_id || '').trim();

const staticData = $getWorkflowStaticData('global');
if (!staticData.seenPairs) staticData.seenPairs = {};

let message;
if (!pairId) {
  message = 'Missing pair_id — this link looks broken. Nothing was changed.';
} else {
  staticData.seenPairs[pairId] = { status: 'dismissed', at: new Date().toISOString() };
  message = `Marked as not a duplicate. Pair ${pairId} will not be flagged again in future scans.`;
}

return [{ json: {
  html_response: `<html><body style="font-family: sans-serif; padding: 2rem; max-width: 480px;"><p>${message}</p></body></html>`,
} }];
